          const paymentRes = await posService.getPaymentModes(outletIdToPass);
          console.log("[initApp] Fetched payment modes:", paymentRes.data);
          const modes = (paymentRes.data || []).map(r => r.method_name || r.payment_mode).filter(Boolean);
          setPaymentModes(modes.length > 0 ? modes : ['CASH']);
        } catch (e) {
          console.error("Failed to fetch payment modes:", e);
          setPaymentModes(['CASH']); // Fallback
        }

