          const discountRes = await posService.getDiscounts(outletIdToPass);
          setAvailableDiscounts((discountRes.data || []).filter(d => d.is_active));
        } catch (e) {
          console.error("Failed to fetch discounts:", e);
        }

        try {
          const chargesRes = await posService.getAdditionalCharges(outletIdToPass);
          setAvailableCharges((chargesRes.data || []).filter(c => c.is_active));
        } catch (e) {
          console.error("Failed to fetch additional charges:", e);
        }"

